// Tidy each Graph file into the fields the rest of the workflow uses,
// and URL-decode the name (Graph can return %20 etc. — the episode's merge pitfall).
function decode(name) {
  try {
    return decodeURIComponent(name);
  } catch (e) {
    return name; // a literal "%" in a real file name (e.g. "50% discount.pdf") isn't encoding — keep it
  }
}

// Files in a subfolder are named "Folder/File.ext" (shown in citations; avoids name clashes between folders).
const folderOf = item => decode((item.json.parentReference?.path ?? '').split('root:')[1] ?? '').replace(/^\//, '');

return $input.all().map(item => ({
  json: {
    file_id: item.json.id,                                        // the real file ID (for download)
    file_name: (folderOf(item) ? folderOf(item) + '/' : '') + decode(item.json.name),   // the merge key
    content_hash: item.json.file?.hashes?.quickXorHash ?? null,   // Microsoft's content fingerprint
    graph_last_modified: item.json.lastModifiedDateTime,
  },
}));

// Turn each SharePoint list item into { file_name, last_modified } — top level + one subfolder level.
// The name only exists inside webUrl, URL-encoded (Shared%20Documents/My%20File.pdf).
function decode(s) {
  try { return decodeURIComponent(s); } catch (e) { return s; }
}

const LIBRARY = '/sites/__SITE_PATH__/Shared%20Documents/';
const out = [];

for (const item of $input.all()) {
  const url = item.json.webUrl ?? '';
  const i = url.indexOf(LIBRARY);
  if (i === -1) continue;                      // not in the Documents library
  const rest = url.slice(i + LIBRARY.length);  // "2018_Annual%20Report.pdf"  or  "Tag/file.pdf"
  const parts = rest.split('/');
  if (parts.length > 2) continue;              // deeper than one subfolder → Branch A doesn't list these either
  if (parts.length === 2 && /^dnu$|do not use/i.test(decode(parts[0]).trim())) continue;   // skipped folder
  out.push({
    json: {
      file_name: decode(rest),                 // "File.pdf" or "Tag/File.pdf" — matches Branch A's file_name
      last_modified: item.json.lastModifiedDateTime,
    },
  });
}
return out;

// Compare SharePoint NOW against what the database REMEMBERS from last run.
// Output: one item per file that needs work, tagged action = new | updated | touch | deleted.
// Nothing changed → no output → the run stops here (the episode's "it simply stops").

// current SharePoint files, minus OLD_ / Do Not Use (filtered before this node)
const now = $('Skip outdated files').all().map(i => i.json);
const memory = $('Read document_metadata').all()
  .map(i => i.json)
  .filter(r => r.file_id);               // skip the empty placeholder from "Always Output Data"

const memoryById = new Map(memory.map(r => [r.file_id, r]));
const nowIds = new Set(now.map(f => f.file_id));
const out = [];

for (const f of now) {
  const m = memoryById.get(f.file_id);

  if (!m) {                                                   // never seen this ID → NEW
    out.push({ json: { action: 'new', ...f } });
    continue;
  }

  const newer   = new Date(f.last_modified) > new Date(m.last_modified);
  const renamed = f.file_name !== m.file_name;
  const contentChanged = (f.content_hash && m.content_hash)
    ? f.content_hash !== m.content_hash                       // hash is the real test
    : newer;                                                  // no hash? fall back to the timestamp

  if (contentChanged || renamed) {
    out.push({ json: { action: 'updated', ...f } });          // reprocess (rename too, so citations show the new name)
  } else if (newer) {
    out.push({ json: { action: 'touch', ...f } });            // only tags/timestamp moved → just update the row
  }
  // otherwise unchanged → nothing to do
}

for (const m of memory) {
  if (!nowIds.has(m.file_id)) {                               // remembered, but gone from SharePoint → DELETED
    out.push({ json: { action: 'deleted', file_id: m.file_id, file_name: m.file_name } });
  }
}

return out;

