// The download returns only the file bytes; re-attach the file's details from before the download.
const info = $('Batch: 4 files per run').item.json;   // the matching item from before the download
const ext = (info.file_name.split('.').pop() || '').toLowerCase();

return {
  json: { ...info, extension: ext },   // file_id, file_name, content_hash, action … + extension
  binary: $input.item.binary,          // keep the downloaded file
};

// Wrap each spreadsheet row with the file it came from (the episode: "JSON right next to the file ID and file name"),
// plus the tab it came from (_sheet), so the agent can tell tabs apart.
const info = $('One item per sheet').item.json;
return {
  json: {
    file_id: info.file_id,
    file_name: info.file_name,
    last_modified: info.last_modified,
    content_hash: info.content_hash,
    row_data: { _sheet: info.sheet_name, ...$input.item.json },   // the whole row, exactly as in the sheet
  },
};

// One item per spreadsheet FILE (not per row), with how many rows were stored.
// Built from every file that entered the spreadsheet path — so a sheet that yielded 0 rows
// still gets marked as handled instead of coming back as "new" every run.
const counts = new Map();
for (const { json } of $('Shape rows').all()) {
  counts.set(json.file_id, (counts.get(json.file_id) ?? 0) + 1);
}

return $('Route by file type').all(0).map(({ json: f }) => ({   // output 0 = spreadsheet
  json: {
    file_id: f.file_id,
    file_name: f.file_name,
    last_modified: f.last_modified,
    content_hash: f.content_hash,
    row_count: counts.get(f.file_id) ?? 0,
  },
}));

// One OCR request per part, read straight from the file — no separate base64 step, so the
// execution stores the document once instead of twice. Mistral takes the part inline as a
// data URL (data:<type>;base64,<bytes>) and is asked to DESCRIBE each image it finds
// (the episode's "it leaves a description"), which ends up in the searchable text.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const info = items[i].json;                       // file details + part / of / part_mime
  const b64 = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64');
  const dataUrl = `data:${info.part_mime};base64,${b64}`;
  const document = info.part_mime.startsWith('image/')
    ? { type: 'image_url', image_url: dataUrl }
    : { type: 'document_url', document_url: dataUrl };
  out.push({
    json: { ...info, body: { model: 'mistral-document-ai-2512', document, include_image_base64: true,
      bbox_annotation_format: { type: 'json_schema', json_schema: { name: 'image_description', strict: true, schema: {
      type: 'object', additionalProperties: false, required: ['description'],
      properties: { description: { type: 'string',
        description: 'One or two sentences describing what the image shows, for someone who cannot see it.' } } } } },
    } },
    pairedItem: { item: i },
  });
}
return out;

// Check each PART's OCR result: ok / retry / failed. (Emptiness is judged per FILE in the next node,
// so a blank back-cover part doesn't fail a whole manual.)
const res = $input.item.json;
const info = { ...$('Build OCR request').item.json };
delete info.body;                                        // drop the (huge) base64 request

const status = res.statusCode;
const pages = Array.isArray(res.body?.pages) ? res.body.pages : [];
const cleanMsg = m => String(m ?? '').replace(/[A-Za-z0-9+/=]{100,}/g, '<file>').slice(0, 300);

let ocr_status, reason = null;
if (status === 200) {
  ocr_status = 'ok';
} else if (!status || status === 408 || status === 429 || status >= 500) {
  ocr_status = 'retry'; reason = `HTTP ${status ?? 'timeout'} — temporary, will retry next run`;
} else {
  ocr_status = 'failed'; reason = `HTTP ${status}: ${cleanMsg(res.body?.message ?? JSON.stringify(res.body))}`;
}
return { json: { ...info, ocr_status, reason, pages } };

// Images are already small and single-page: send them to OCR as one part.
return $input.all().map((item, i) => ({
  json: { ...item.json, part: 1, of: 1, part_mime: item.json.extension === 'png' ? 'image/png' : 'image/jpeg' },
  binary: item.binary,
  pairedItem: { item: i },
}));

// One item per ≤10-page PDF part (Azure OCR limit), in page order, carrying the file's details.
// Gotenberg names parts <name>_0.pdf, <name>_1.pdf … → sort numerically.
const out = [];
$input.all().forEach((item, i) => {
  const info = $('Attach file info').itemMatching(i).json;
  const bins = Object.values(item.binary ?? {})
    .sort((a, b) => (a.fileName ?? '').localeCompare(b.fileName ?? '', undefined, { numeric: true }));
  bins.forEach((bin, p) => out.push({
    json: { ...info, part: p + 1, of: bins.length, part_mime: 'application/pdf' },
    binary: { data: bin },
    pairedItem: { item: i },
  }));
});
return out;

// Put each file back together: parts in page order → one document. All-or-nothing:
// any part retry → whole file retry; any part failed / missing / no usable text → whole file failed.
// Exception: a part whose OCR result Azure's content filter BLOCKED (content_safety_violation) can never
// succeed, so keep the rest of the document and put a visible note where those pages were.
const byFile = new Map();
for (const { json } of $input.all()) {
  if (!byFile.has(json.file_id)) byFile.set(json.file_id, []);
  byFile.get(json.file_id).push(json);
}

const out = [];
for (const parts of byFile.values()) {
  parts.sort((a, b) => a.part - b.part);
  const { part, of, part_mime, pages: _p, ocr_status: _s, reason: _r, ...file } = parts[0];

  const isBlocked = p => p.ocr_status === 'failed' && /content_safety_violation/.test(p.reason ?? '');
  const blocked = parts.filter(isBlocked);
  const allPages = [];
  for (const p of parts) {
    if (isBlocked(p) && blocked.length < parts.length) {
      allPages.push({ markdown: `*[Pages ${(p.part - 1) * 10 + 1}–${p.part * 10} of ${file.file_name} could not be read: Azure's content filter blocked the OCR result.]*`, images: [] });
    } else allPages.push(...(p.pages ?? []));
  }
  allPages.forEach((pg, i) => { pg.index = i; });            // renumber pages across parts

  const markdown = allPages.map(p => p.markdown ?? '').join('\n\n');
  const imageCount = allPages.reduce((n, p) => n + (p.images?.length ?? 0), 0);
  const realText = markdown.replace(/!\[[^\]]*\]\([^)]*\)/g, '').trim();

  let ocr_status = 'ok', reason = null;
  const bad = s => parts.find(p => p.ocr_status === s && !(isBlocked(p) && blocked.length < parts.length));
  if (bad('retry'))                      { ocr_status = 'retry';  reason = `part ${bad('retry').part}/${of}: ${bad('retry').reason}`; }
  else if (bad('failed'))                { ocr_status = 'failed'; reason = `part ${bad('failed').part}/${of}: ${bad('failed').reason}`; }
  else if (parts.length !== of)          { ocr_status = 'failed'; reason = `only ${parts.length} of ${of} parts came back`; }
  else if (realText.length < 20 && !imageCount) {
    if (String(parts[0].part_mime).startsWith('image/')) { ocr_status = 'describe'; reason = 'photo with no text'; }   // → described by GPT
    else { ocr_status = 'failed'; reason = 'OCR returned no usable text'; }
  }

  out.push({ json: { ...file, ocr_status, reason, parts: of, page_count: allPages.length,
                     image_count: imageCount, text_chars: realText.length, markdown, pages: allPages } });
}
return out;

// Gotenberg decides how to read a file from the extension in the upload's file name.
// SharePoint names with apostrophes etc. can arrive mangled, so upload under a plain name.
// (The real name stays in file_name for citations.)
return $input.all().map((item, i) => {
  const ext = item.json.extension;
  item.binary.data.fileName = `document.${ext}`;
  item.binary.data.fileExtension = ext;
  return { json: item.json, binary: item.binary, pairedItem: { item: i } };
});

// The episode's image step: OCR left placeholders like ![img-0.jpeg](img-0.jpeg) in each page.
// Keep only meaningful images (skip tiny logos/icons and repeats), give each a public URL,
// and put that URL into the text where the image was. The URLs are predictable, so the
// text can be finished now; the actual upload happens on a side branch.
const PUBLIC_BASE = 'http://localhost:8000/storage/v1/object/public/document-images/'; // change for production
const MIN_SIDE = 80, MIN_AREA = 150 * 150;

return $input.all().map((item, i) => {
  const f = item.json;
  const seen = new Set();
  const uploads = [];

  const pageTexts = (f.pages ?? []).map(page => {
    let md = page.markdown ?? '';
    for (const img of page.images ?? []) {
      const w = (img.bottom_right_x ?? 0) - (img.top_left_x ?? 0);
      const h = (img.bottom_right_y ?? 0) - (img.top_left_y ?? 0);
      const b64 = String(img.image_base64 ?? '').replace(/^data:[^,]+,/, '');
      const key = b64.length + ':' + b64.slice(0, 200) + b64.slice(-200);   // cheap fingerprint
      const placeholder = `![${img.id}](${img.id})`;
      const tooSmall = w < MIN_SIDE || h < MIN_SIDE || w * h < MIN_AREA;

      if (!b64 || tooSmall || seen.has(key)) {           // drop it from the text
        md = md.split(placeholder).join('');
        continue;
      }
      seen.add(key);
      const path = `${f.file_id}/p${page.index + 1}-${img.id}`;
      uploads.push({ path, b64, mime: img.id.endsWith('.png') ? 'image/png' : 'image/jpeg' });
      let desc = '';
      try { desc = JSON.parse(img.image_annotation ?? '{}').description ?? ''; } catch (e) { desc = String(img.image_annotation ?? ''); }
      const alt = (desc || `Image from ${f.file_name}`).replace(/[\[\]\n]/g, ' ').trim();
      md = md.split(placeholder).join(`![${alt}](${PUBLIC_BASE}${path})\n*Image, page ${page.index + 1}: ${alt}*`);
    }
    return md;
  });

  const { pages, ...rest } = f;                          // drop raw OCR pages (large) from here on
  return { json: { ...rest, markdown: pageTexts.join('\n\n'), uploads, images_kept: uploads.length },
           pairedItem: { item: i } };
});

// One item per image to upload (may be zero — that's fine, this side branch just ends).
const out = [];
$input.all().forEach((item, i) => {
  for (const u of item.json.uploads ?? []) {
    out.push({ json: { path: u.path, b64: u.b64, mime: u.mime }, pairedItem: { item: i } });
  }
});
return out;

// Split the document into blocks (paragraphs, tables, lists stay whole because they have no blank lines
// inside) and number them, so the model can say "cut after block 41" instead of rewriting text.
const MAX_BLOCK = 4000;   // very long blocks (logs, huge tables) are split on line breaks so they can still be chunked
const blocks = [];
for (const b of $input.item.json.markdown.split(/\n\s*\n/).map(b => b.trim()).filter(Boolean)) {
  if (b.length <= MAX_BLOCK) { blocks.push(b); continue; }
  let cur = '';
  for (const line of b.split('\n')) {
    if (cur && cur.length + line.length + 1 > MAX_BLOCK) { blocks.push(cur); cur = ''; }
    cur = cur ? cur + '\n' + line : line;
  }
  if (cur) blocks.push(cur);
}
const numbered = blocks.map((b, n) => `[${n}] ${b}`).join('\n\n');

const prompt = `You split a document into chunks for a search system. The document is given as numbered blocks [n].
Return ONLY json in this exact shape: {"chunks":[{"start":0,"end":12,"title":"short section title"}]}

Rules:
- Cover every block exactly once, in order: the first chunk starts at 0, each chunk starts right after the previous one ends, the last chunk ends at ${blocks.length - 1}.
- Cut where the topic changes. Never separate a heading from the section beneath it. Keep numbered or bulleted lists, tables and step-by-step procedures intact. Keep an argument together with its conclusion.
- Aim for 500–2,000 tokens per chunk (about 2,000–8,000 characters). Never exceed about 10,000 characters.

Document: ${$input.item.json.file_name}

${numbered}`;

return { json: { ...$input.item.json, blocks, prompt } };

// Turn the model's cut points into actual chunks of the ORIGINAL text. If the answer is unusable,
// fall back to size-based cutting at block boundaries — a file is never lost to a bad JSON reply.
const MAX_CHARS = 10000, TARGET = 6000;
const out = [];

$input.all().forEach((item, i) => {
  const doc = $('Number blocks').itemMatching(i).json;
  const blocks = doc.blocks;
  let ranges = [];
  // n8n's LLM node already parses JSON replies into fields ({ chunks: [...] });
  // older versions return the raw text instead — accept both.
  let parsed = item.json;
  if (!Array.isArray(parsed.chunks)) {
    try { parsed = JSON.parse(item.json.text ?? item.json.response ?? '{}'); } catch (e) { parsed = {}; }
  }
  // The model's real decision is WHERE each section starts. Use its start points as cut
  // positions and rebuild contiguous ranges — small slips (an overlap, an end past the last
  // block) get repaired instead of throwing away a good plan.
  const last = blocks.length - 1;
  const starts = [...new Set([0, ...(parsed.chunks ?? [])
      .map(c => Math.round(Number(c.start)))
      .filter(s => Number.isFinite(s) && s >= 0 && s <= last)])].sort((a, b) => a - b);
  const valid = (parsed.chunks ?? []).length > 0;
  ranges = starts.map((s, k) => [s, k + 1 < starts.length ? starts[k + 1] - 1 : last]);
  if (!valid) {                                         // fallback: pack blocks up to ~TARGET chars
    ranges = []; let s = 0, size = 0;
    blocks.forEach((b, n) => {
      if (size > 0 && size + b.length > TARGET) { ranges.push([s, n - 1]); s = n; size = 0; }
      size += b.length;
    });
    ranges.push([s, blocks.length - 1]);
  }

  // Enforce the episode's ~2,500-token ceiling: split any oversized chunk at block boundaries
  const pieces = [];
  for (const [s, e] of ranges) {
    let cur = [];
    for (let n = s; n <= e; n++) {
      if (cur.length && (cur.join('\n\n') + blocks[n]).length > MAX_CHARS) { pieces.push(cur); cur = []; }
      cur.push(blocks[n]);
    }
    if (cur.length) pieces.push(cur);
  }

  // Merge undersized neighbours (e.g. a one-page agenda cut into five tiny pieces) up to ~TARGET,
  // so every chunk carries enough context to be useful on its own.
  const MIN_CHARS = 1500;
  const size = a => a.join('\n\n').length;
  const merged = [];
  for (const p of pieces) {
    const prev = merged[merged.length - 1];
    if (prev && (size(prev) < MIN_CHARS || size(p) < MIN_CHARS) && size(prev) + size(p) + 2 <= TARGET) prev.push(...p);
    else merged.push([...p]);
  }

  const { blocks: _b, prompt: _p, markdown: _m, uploads: _u, ...file } = doc;
  merged.forEach((p, k) => out.push({
    json: { ...file, chunk_index: k, chunk_count: merged.length, plan: valid ? 'agentic' : 'fallback',
            content: p.join('\n\n') },
    pairedItem: { item: i },
  }));
});
return out;

// Back to one item per FILE with its chunk count, for the catalog card + log.
const files = new Map();
for (const { json } of $('Cut chunks').all()) {
  if (!files.has(json.file_id)) files.set(json.file_id, { ...json, content: undefined });
}
return [...files.values()].map(f => ({ json: f }));

// The upload step continues on error so one bad image can't block a document — which also
// means failures are silent. Count them per file and log them (the episode's "success that isn't").
const byFile = new Map();
$input.all().forEach((item, i) => {
  if (!item.json.error) return;
  const fileId = $('One item per image').itemMatching(i).json.path.split('/')[0];
  byFile.set(fileId, (byFile.get(fileId) ?? 0) + 1);
});
return [...byFile].map(([file_id, n]) => ({ json: { file_id, message: `${n} image upload(s) failed` } }));

// .log / .txt / .md need no OCR: read the text and hand it to chunking in the same shape
// the OCR path produces (no images).
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const text = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  out.push({ json: { ...items[i].json, markdown: text, uploads: [], images_kept: 0 }, pairedItem: { item: i } });
}
return out;

// Gotenberg couldn't convert or split this file — e.g. Outlook "Save as PDF" files carry a non-standard
// PageLayout entry that Gotenberg's PDF library rejects outright. Mistral OCR reads PDF, DOCX and PPTX
// directly (up to 30 pages / 30 MB), so send the ORIGINAL file as a single part instead of giving up.
// If it's too big for that, OCR rejects it and the file is marked failed with that reason.
const MIME = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  doc: 'application/msword',
};
const out = [];
$input.all().forEach((item, i) => {
  let src;
  try { src = $('Safe file name').itemMatching(i); } catch (e) { return; }   // can't trace the file → retried next run
  const info = src.json;
  out.push({
    json: { ...info, part: 1, of: 1, part_mime: MIME[info.extension] ?? 'application/pdf' },
    binary: { data: src.binary.data },
    pairedItem: { item: i },
  });
});
return out;

// Excel files are zip archives. n8n's unzip step only accepts files labelled .zip, so hand it a
// relabelled copy; the original stays in `data` for reading the rows.
return $input.all().map((item, i) => ({
  json: item.json,
  binary: {
    data: item.binary.data,
    workbook_zip: { ...item.binary.data, fileName: 'workbook.zip', fileExtension: 'zip', mimeType: 'application/zip' },
  },
  pairedItem: { item: i },
}));

// Every tab, not just the first: read the tab names from the workbook's table of contents
// (xl/workbook.xml) and emit one item per tab, carrying the original file so the next step reads that tab.
const decode = s => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = $('Prepare workbook').itemMatching(i);
  const bin = items[i].binary ?? {};
  const key = Object.keys(bin).find(k => /(^|\/)workbook\.xml$/i.test(bin[k].fileName ?? ''));
  let names = [];
  if (key) {
    const xml = (await this.helpers.getBinaryDataBuffer(i, key)).toString('utf8');
    names = [...xml.matchAll(/<(?:\w+:)?sheet\b[^>]*?\bname="([^"]*)"/g)].map(m => decode(m[1]));
  }
  if (!names.length) names = [''];   // tab list unreadable → read the first tab, as before
  for (const sheet_name of names) {
    out.push({ json: { ...src.json, sheet_name, sheet_count: names.length }, binary: { data: src.binary.data }, pairedItem: { item: i } });
  }
}
return out;

// A photo with no text in it (OCR found nothing). Pick up the original image again so GPT can look at it.
const originals = new Map($('Image: one part').all().map(it => [it.json.file_id, it]));
const out = [];
$input.all().forEach((item, i) => {
  const src = originals.get(item.json.file_id);
  if (!src?.binary?.data) return;                     // not found → file stays unmarked and is retried next run
  out.push({ json: item.json, binary: { data: src.binary.data }, pairedItem: { item: i } });
});
return out;

// Ask gpt-5.4-mini (vision) for a factual description, so the photo can be found by search.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const f = items[i].json;
  const b64 = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64');
  const mime = f.extension === 'png' ? 'image/png' : 'image/jpeg';
  out.push({ json: { ...f, body: {
    model: 'gpt-5.4-mini', reasoning_effort: 'low', max_completion_tokens: 400,
    messages: [
      { role: 'system', content: 'You describe images from a company document library so they can be found by search. Be factual and specific: what is shown, activity, equipment, setting, any visible text. 2-4 sentences. Do not guess who people are.' },
      { role: 'user', content: [
        { type: 'text', text: `Describe this image (file name: ${f.file_name}).` },
        { type: 'image_url', image_url: { url: `data:${mime};base64,${b64}` } } ] },
    ] } }, pairedItem: { item: i } });
}
return out;

// Turn GPT's description into the file's text, then send it back through "Route OCR result":
// ok → linked, chunked and embedded like any other file; failed → marked failed with the reason.
return $input.all().map((item, i) => {
  const { body, ...f } = $('Photo: build request').itemMatching(i).json;
  const desc = String(item.json.choices?.[0]?.message?.content ?? '').trim();
  if (desc.length < 20) {
    const err = item.json.error?.message ?? item.json.error ?? 'empty description';
    return { json: { ...f, ocr_status: 'failed', reason: `photo with no text; description failed: ${String(err).slice(0, 150)}` }, pairedItem: { item: i } };
  }
  const markdown = `*Photo (${f.file_name}): ${desc}*`;
  return { json: { ...f, ocr_status: 'ok', reason: null, page_count: 1, image_count: 0, text_chars: desc.length,
                   markdown, pages: [{ index: 0, markdown, images: [] }] }, pairedItem: { item: i } };
});

// The library's top level plus every subfolder, except "DNU" / "Do Not Use" folders (skipped on purpose).
// One level deep: files in a sub-subfolder are not read.
const folders = [''];
for (const page of $input.all())
  for (const f of page.json.value ?? [])
    if (f.folder && !/^dnu$|do not use/i.test(f.name.trim())) folders.push(f.name);
return folders.map(folder => ({ json: { folder, path: folder ? `root:/${encodeURIComponent(folder)}:` : 'root' } }));

// n8n's unzip step decides by the file's extension label, so make sure a zip is labelled as one.
return $input.all().map((item, i) => ({
  json: item.json,
  binary: { data: { ...item.binary.data, fileName: 'archive.zip', fileExtension: 'zip', mimeType: 'application/zip' } },
  pairedItem: { item: i },
}));

// Unzipped archive → table rows. Reads rainfall distribution tables (.tbl, NRCS WinTR rainfall-table format: a header
// line "NAME  increment", then cumulative fractions, 5 per line, from time 0). Each table becomes rows
// { _sheet: <file name>, Distribution: NAME, "Time (hr)", "Cumulative fraction" } in document_rows, so the agent
// can query them with SQL. (The tab is the file name: different files can carry the same internal NAME.)
// Anything else inside an archive is not read; an archive with nothing readable is marked skipped.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  let f;
  try { f = $('Attach file info').itemMatching(i).json; } catch (e) { continue; }   // can't trace → retried next run
  const rows = []; let tables = 0;
  for (const [key, bin] of Object.entries(items[i].binary ?? {})) {
    if (!/\.tbl$/i.test(bin.fileName ?? '')) continue;
    const lines = (await this.helpers.getBinaryDataBuffer(i, key)).toString('latin1').split(/\r?\n/).filter(l => l.trim());
    if (!lines.length) continue;
    const head = lines[0].trim().split(/\s+/);
    const inc = Number(head[head.length - 1]);
    const named = head.length > 1 && !isNaN(inc);
    const tab = String(bin.fileName).split('/').pop().replace(/\.tbl$/i, '');
    const name = named ? head.slice(0, -1).join(' ') : tab;
    const step = named && inc > 0 ? inc : 0.1;
    const values = lines.slice(named ? 1 : 0).join(' ').trim().split(/\s+/).map(Number).filter(v => !isNaN(v));
    if (!values.length) continue;
    tables++;
    values.forEach((v, k) => rows.push({ _sheet: tab, Distribution: name, 'Time (hr)': Math.round(k * step * 1000) / 1000, 'Cumulative fraction': v }));
  }
  out.push({ json: { file_id: f.file_id, file_name: f.file_name, last_modified: f.last_modified, content_hash: f.content_hash,
                     rows, message: tables ? `${tables} rainfall distribution tables (.tbl) → ${rows.length} rows` : 'archive: nothing readable inside' },
             pairedItem: { item: i } });
}
return out;
